package dev.industrialtechnology.railway;
import net.minecraft.item.*;import net.minecraft.entity.player.EntityPlayer;import net.minecraft.world.World;import net.minecraft.util.ChatComponentText;
public final class ItemRollingStock extends Item {
 public final StockType type;public ItemRollingStock(StockType t){type=t;setMaxStackSize(1);setUnlocalizedName("industrialtech.stock_"+t.ordinal());setTextureName("industrialtech:stock_"+t.ordinal());setCreativeTab(dev.industrialtechnology.core.ModRegistry.TAB);}
 @Override public boolean onItemUse(ItemStack s,EntityPlayer p,World w,int x,int y,int z,int side,float a,float b,float c){if(w.isRemote)return true;if(!p.canPlayerEdit(x,y,z,side,s))return false;TrackWorld.Cursor cursor=TrackWorld.nearest(w,x+a,y+b,z+c,4);if(cursor==null){p.addChatMessage(new ChatComponentText("Place near the centerline of an Industrial railway segment."));return false;}EntityRollingStock e=new EntityRollingStock(w,type,cursor,p.getUniqueID());e.restoreItem(s);e.stock=type;e.owner=p.getUniqueID();e.front=e.rear=null;e.rail=cursor;e.pose();if(!e.safeAt(cursor)){p.addChatMessage(new ChatComponentText("The whole vehicle needs connected, loaded track and 3 m clearance."));return false;}if(!w.getEntitiesWithinAABB(EntityRollingStock.class,e.boundingBox.expand(.1,0,.1)).isEmpty()){p.addChatMessage(new ChatComponentText("Another vehicle occupies that position."));return false;}if(w.spawnEntityInWorld(e)&&!p.capabilities.isCreativeMode)s.stackSize--;return true;}
 @Override public void addInformation(ItemStack s,EntityPlayer p,java.util.List l,boolean a){l.add(type.title);l.add("Standard gauge 1.435 m; "+type.length+" m long");l.add(type.engine()?"Right click: drive; sneak-right click: controls":"Right click: inventory / passenger seat");l.add("Sneak-hit while stopped and uncoupled: pack up");}
}
